echo "K18 SWEEP viewBox/path pins in tests: $(grep -rlE "viewBox|V\(\\\\d|getAttribute\('d'\)|buildPeakShape|waveformPeakColumns" $S/app --include='*.test.ts' --include='*.test.tsx' 2>/dev/null | sed "s#$S/##" | sort | tr '\n' ' ')"
